def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    cnt = Counter()
    for row in grid:
        cnt.update(row)
    # find color that forms a complete row or column (the "solid" color)
    solid = None
    for c in set(cnt):
        if c == 0:
            continue
        rows_full = any(all(x == c for x in row) for row in grid)
        cols_full = any(all(grid[r][j] == c for r in range(h)) for j in range(w))
        if rows_full or cols_full:
            solid = c
            break
    out = []
    for row in grid:
        new = []
        for x in row:
            if x == 0:
                new.append(0)
            elif solid is not None and x == solid:
                new.append(0)
            else:
                new.append(2)
        out.append(new)
    # drop rows/cols that are entirely solid-colored (the solid separator lines)
    if solid is not None:
        out = [r for r in out if not all(x == 0 for x in r)]
        if out:
            keep = [j for j in range(w) if any(r[j] != 0 for r in out)]
            if len(keep) < w:
                out = [[r[j] for j in keep] for r in out]
    return out
